using System;
using System.Collections;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SoulStigmaEffect", menuName = "Data/Battle/Effects/Sothis/SoulStigma Effect")]
public class SoulStigmaEffect : Effect
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[NonSerialized]
	private int timesAmount;

	[SerializeField]
	private PurifyAction purifyAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedWhereXTimes(purifyAction.GetActionDescription(amount).RemoveLast(), amount == EffectsValues.NO_VALUE, "", removeThirdArgument: true)) + AppendedDescription();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		timesAmount = 0;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (timesAmount == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SoulStigmaCoroutine(effectAmount, effectOwner));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		timesAmount++;
		return effectAmount;
	}

	private IEnumerator SoulStigmaCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.1f);
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
		{
			effectOwner.GetComponent<PlayerEffects>().IsEffectActive(this);
			yield return new WaitForSeconds(0.3f);
			for (int i = 0; i < timesAmount; i++)
			{
				if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
				{
					GameObject gameObject = currentCorruptedAnimals.activeCorruptedAnimals.PickRandom();
					CorruptionStats component = gameObject.GetComponent<CorruptionStats>();
					SpawnSecondVFX(GetVFXOwnerPosition(gameObject), 3f);
					PlayEffectActivationSFX();
					component.Purify(effectAmount, null);
					if (i < timesAmount - 1)
					{
						yield return new WaitForSeconds(0.3f);
					}
				}
			}
		}
		timesAmount = 0;
	}
}
